def no_null(x, path="wf"):
    if x is None:
        raise SystemExit("null at " + path)
    if isinstance(x, dict):
        for k, v in x.items():
            no_null(v, path + "." + k)
    if isinstance(x, list):
        for i, v in enumerate(x):
            no_null(v, path + "[" + str(i) + "]")


